import ast


def imported_modules(source):
    names = set()
    for node in ast.walk(ast.parse(source)):
        if isinstance(node, ast.Import):
            names.update(alias.name for alias in node.names)
        elif isinstance(node, ast.ImportFrom) and node.level == 0:
            names.add(node.module)
    return sorted(names)


def layer_of(module, layers):
    top = module.split(".")[0]
    return layers.index(top) if top in layers else None


def violations(modules, layers):
    found = []
    for name, source in modules.items():
        own = layer_of(name, layers)
        for imported in imported_modules(source):
            other = layer_of(imported, layers)
            if own is not None and other is not None and other > own:
                found.append((name, imported))
    return sorted(found)

