from pathlib import Path


def plan_sync(source, target):
    actions = []
    for name in sorted(source.keys() | target.keys()):
        if name not in target:
            actions.append(("copy", name))
        elif name not in source:
            actions.append(("delete", name))
        elif source[name] != target[name]:
            actions.append(("update", name))
    return actions


def read_folder(folder):
    return {p.name: p.read_text() for p in Path(folder).iterdir() if p.is_file()}


def sync(src_dir, dst_dir):
    src, dst = Path(src_dir), Path(dst_dir)
    actions = plan_sync(read_folder(src), read_folder(dst))
    for action, name in actions:
        if action == "delete":
            (dst / name).unlink()
        else:
            (dst / name).write_text((src / name).read_text())
    return actions

