import re
from dataclasses import dataclass


@dataclass(frozen=True)
class Money:
    cents: int
    currency: str

    def __post_init__(self):
        if self.cents < 0:
            raise ValueError(f"negative amount: {self.cents}")
        if not re.fullmatch(r"[A-Z]{3}", self.currency):
            raise ValueError(f"bad currency: {self.currency!r}")

    def __add__(self, other):
        if other.currency != self.currency:
            raise ValueError(f"cannot add {other.currency} to {self.currency}")
        return Money(self.cents + other.cents, self.currency)

    def split(self, n):
        share, extra = divmod(self.cents, n)
        return [Money(share + (1 if i < extra else 0), self.currency) for i in range(n)]


class Account:
    def __init__(self, number, owner):
        self.number = number
        self.owner = owner
        self.balance = Money(0, "EUR")

    def deposit(self, money):
        self.balance = self.balance + money

    def __eq__(self, other):
        return isinstance(other, Account) and other.number == self.number

    def __hash__(self):
        return hash(self.number)

