from enum import Enum


class Status(Enum):
    DRAFT = "draft"
    SUBMITTED = "submitted"
    PAID = "paid"
    SHIPPED = "shipped"
    CANCELLED = "cancelled"


class InvalidTransition(Exception):
    pass


TRANSITIONS = {
    (Status.DRAFT, "submit"): Status.SUBMITTED,
    (Status.SUBMITTED, "pay"): Status.PAID,
    (Status.PAID, "ship"): Status.SHIPPED,
    (Status.DRAFT, "cancel"): Status.CANCELLED,
    (Status.SUBMITTED, "cancel"): Status.CANCELLED,
}


class Order:
    def __init__(self):
        self.status = Status.DRAFT
        self.history = [Status.DRAFT]

    def apply(self, action):
        new = TRANSITIONS.get((self.status, action))
        if new is None:
            raise InvalidTransition(f"cannot {action} a {self.status.value} order")
        self.status = new
        self.history.append(new)

    def allowed_actions(self):
        return sorted(action for state, action in TRANSITIONS if state == self.status)

