        return [replace(self._rows[sku]) for sku in sorted(self._rows)]


class SqliteProductRepository:
    def __init__(self, conn):
        self.conn = conn
        conn.execute(
            "CREATE TABLE IF NOT EXISTS products"
            " (sku TEXT PRIMARY KEY, stock INTEGER NOT NULL)"
        )

    def add(self, product):
        self.conn.execute(
            "INSERT OR REPLACE INTO products (sku, stock) VALUES (?, ?)",
            (product.sku, product.stock),
        )

    def get(self, sku):
        row = self.conn.execute(
            "SELECT sku, stock FROM products WHERE sku = ?", (sku,)
        ).fetchone()
        return Product(*row) if row is not None else None

    def list(self):
        rows = self.conn.execute("SELECT sku, stock FROM products ORDER BY sku")
        return [Product(*row) for row in rows]

