import copy


class InMemoryUnitOfWork:
    def __init__(self, stock):
        self._stored = stock
        self.stock = None
        self.committed = False

    def __enter__(self):
        self.stock = copy.deepcopy(self._stored)
        return self

    def __exit__(self, *exc_info):
        self.stock = None

    def commit(self):
        self._stored.clear()
        self._stored.update(self.stock)
        self.committed = True


def transfer(uow, from_sku, to_sku, qty):
    with uow:
        available = uow.stock[from_sku]
        if available < qty:
            raise ValueError(f"{from_sku} has {available}, cannot move {qty}")
        uow.stock[from_sku] -= qty
        uow.stock[to_sku] += qty
        uow.commit()

