from dataclasses import dataclass, field


@dataclass(frozen=True)
class OutOfStock:
    sku: str


@dataclass
class Product:
    sku: str
    stock: int
    events: list = field(default_factory=list)

    def reserve(self, qty):
        if qty > self.stock:
            raise ValueError(f"only {self.stock} of {self.sku} left")
        self.stock -= qty
        if self.stock == 0:
            self.events.append(OutOfStock(self.sku))


class MessageBus:
    def __init__(self):
        self.handlers = {}

    def subscribe(self, event_type, handler):
        self.handlers.setdefault(event_type, []).append(handler)

    def publish(self, events):
        for event in events:
            for handler in self.handlers.get(type(event), []):
                handler(event)


def reserve_and_publish(product, qty, bus):
    product.reserve(qty)
    events, product.events = product.events, []
    bus.publish(events)

