from dataclasses import dataclass


@dataclass(frozen=True)
class AddTask:
    task_id: int
    title: str


@dataclass(frozen=True)
class CompleteTask:
    task_id: int


class TaskList:
    def __init__(self):
        self._titles = {}
        self._done = set()

    def execute(self, command):
        match command:
            case AddTask(task_id, title):
                if task_id in self._titles:
                    raise ValueError(f"task {task_id} already exists")
                self._titles[task_id] = title
            case CompleteTask(task_id):
                if task_id not in self._titles:
                    raise KeyError(task_id)
                self._done.add(task_id)
            case _:
                raise TypeError(f"unknown command: {command!r}")

    def open_titles(self):
        return [
            title for task_id, title in self._titles.items()
            if task_id not in self._done
        ]

    def done_count(self):
        return len(self._done)

