from decimal import Decimal
from typing import Protocol


class Rates(Protocol):
    def rate(self, base: str, quote: str) -> Decimal: ...


class HttpRates:
    def __init__(self, client):
        self.client = client

    def rate(self, base, quote):
        response = self.client.get(f"/rates/{base}/{quote}")
        response.raise_for_status()
        return Decimal(str(response.json()["rate"]))


class FakeRates:
    def __init__(self, table):
        self.table = table

    def rate(self, base, quote):
        return self.table[(base, quote)]


def convert(amount, base, quote, rates: Rates):
    if base == quote:
        return amount
    return (amount * rates.rate(base, quote)).quantize(Decimal("0.01"))

