import sqlite3


class EmailTaken(Exception):
    pass


class UserNotFound(Exception):
    pass


class SqliteUsers:
    def __init__(self, conn):
        self.conn = conn
        conn.execute("CREATE TABLE IF NOT EXISTS users (email TEXT PRIMARY KEY)")

    def add(self, email):
        try:
            self.conn.execute("INSERT INTO users (email) VALUES (?)", (email,))
        except sqlite3.IntegrityError as error:
            raise EmailTaken(email) from error

    def get(self, email):
        row = self.conn.execute(
            "SELECT email FROM users WHERE email = ?", (email,)
        ).fetchone()
        if row is None:
            raise UserNotFound(email)
        return row[0]


def handle(action, *args):
    try:
        return 200, action(*args)
    except EmailTaken as error:
        return 409, f"email already registered: {error}"
    except UserNotFound as error:
        return 404, f"no such user: {error}"
    except Exception:
        return 500, "internal error"

