    def __init__(self, inner, ttl, clock):
        self.inner = inner
        self.cache = {}

    def price(self, sku):
        if not self.cache.get(sku):
            self.cache[sku] = self.inner.price(sku)
        return self.cache[sku]

    def invalidate(self, sku):
        del self.cache[sku]

lessons.solution:
import time


class CachedPrices:
    def __init__(self, inner, ttl, clock=time.monotonic):
        self.inner = inner
        self.ttl = ttl
        self.clock = clock
        self._entries = {}

    def price(self, sku):
        now = self.clock()
        entry = self._entries.get(sku)
        if entry is None or now - entry[1] >= self.ttl:
            entry = (self.inner.price(sku), now)
            self._entries[sku] = entry
        return entry[0]

    def invalidate(self, sku):
        self._entries.pop(sku, None)

