import os
import sqlite3
from dataclasses import dataclass


class SqliteRepo:
    def __init__(self, path):
        self.conn = sqlite3.connect(path)
        self.conn.execute("CREATE TABLE IF NOT EXISTS products (name TEXT)")

    def add(self, name):
        self.conn.execute("INSERT INTO products VALUES (?)", (name,))

    def names(self):
        rows = self.conn.execute("SELECT name FROM products ORDER BY name")
        return [name for (name,) in rows]


class Catalog:
    def __init__(self, repo, page_size):
        self.repo = repo
        self.page_size = page_size

    def page(self, number):
        start = (number - 1) * self.page_size
        return self.repo.names()[start:start + self.page_size]


@dataclass
class App:
    settings: object
    repo: object
    catalog: Catalog


@dataclass(frozen=True)
class Settings:
    db_path: str = ":memory:"
    page_size: int = 20

    @classmethod
    def from_env(cls, env):
        raw = env.get("SHOP_PAGE_SIZE", "20")
        if not raw.isdecimal() or int(raw) == 0:
            raise ValueError(f"SHOP_PAGE_SIZE must be a positive integer, not {raw!r}")
        return cls(db_path=env.get("SHOP_DB", ":memory:"), page_size=int(raw))


def build_app(settings, repo=None):
    if repo is None:
        repo = SqliteRepo(settings.db_path)
    return App(settings=settings, repo=repo, catalog=Catalog(repo, settings.page_size))


def main():
    app = build_app(Settings.from_env(os.environ))
    print(f"catalog ready, {app.settings.page_size} products per page")


if __name__ == "__main__":
    main()

